const repo=path.resolve(__dirname,'../..'),root=process.env.PARAMETRES_ORGANISATIONS_ASSET_DIR||repo,read=f=>fs.readFileSync(path.join(root,f),'utf8'),manifest=JSON.parse(fs.readFileSync(path.join(repo,'outils/audits/I18N-PARAMETRES-ORGANISATIONS-871-sources.json'))),old=execFileSync('git',['show',manifest.baseCommit+':plateau-organisations-quetes.js'],{cwd:repo,encoding:'utf8',maxBuffer:4e6}),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'],names=['ouvrirOptionsOrga','renderApercuAvatarOrgaHtml','mettreAJourApercuAvatarOrga','handleOrgaAvatarFileChange'];
