async function setup(page,before=false){await page.route('**/*',r=>r.abort());await page.setContent('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body class="plateau-body"><div id="modal-postes" class="modal-overlay"><div class="modal-box"><div class="modal-header"><div id="postes-modal-title" class="modal-title"></div><button class="modal-close" aria-label="Fermer">×</button></div><div id="postes-body" class="modal-body"></div></div></div></body></html>');await page.addStyleTag({content:read('style.css')});await page.addScriptTag({content:read('i18n/i18next.min.js')});await page.evaluate(types=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.TYPES_ORGANISATIONS=types;window.state={country:'republic',pa:12,arg:4000,inventory:[{id:'intact'}],progression:{stage:3}};window.calls=[];window.reads=[];window.previewCalls=[];window.getOrgaById=id=>{reads.push(id);return state.orga;};window.getAvatarHtmlPost=(...args)=>{previewCalls.push(args);return '<div style="width:56px;height:56px" data-preview="opaque"></div>';};for(const f of ['toggleVisibiliteOrga','dissoudreOrga'])window[f]=(...args)=>calls.push([f,...args]);window.sauvegarderOptionsOrga=(...args)=>calls.push(['sauvegarderOptionsOrga',...args,form()]);window.showToast=(...args)=>calls.push(['toast',...args]);for(const f of ['fetch','sbRpc','saveState','sbUploadOrgAvatar','deduireCoutOrdre'])window[f]=(...args)=>{calls.push([f,...args]);throw Error('Appel métier interdit');};window.form=()=>({fields:[...document.querySelectorAll('#postes-body input:not([type=file])')].map(e=>[e.id,e.value]),file:_orgaAvatarFileTemp?{name:_orgaAvatarFileTemp.name,size:_orgaAvatarFileTemp.size,type:_orgaAvatarFileTemp.type}:null});window.snapshot=()=>JSON.stringify({state,calls,reads,previewCalls,form:form()});window.visible=()=>({title:document.getElementById('postes-modal-title').textContent,body:document.getElementById('postes-body').textContent,form:form(),placeholders:[...document.querySelectorAll('#postes-body input')].map(e=>e.getAttribute('placeholder')),handlers:[...document.querySelectorAll('#postes-body [onclick],#postes-body [oninput],#postes-body [onchange]')].map(e=>[e.getAttribute('onclick'),e.getAttribute('oninput'),e.getAttribute('onchange')]),open:document.getElementById('modal-postes').className});document.querySelector('.modal-close').onclick=()=>document.getElementById('modal-postes').classList.remove('open');},regles());for(const f of ['i18n/resources.js','i18n/plateau-resources.js','i18n/organization-settings-resources.js','i18n/plateau-init.js'])await page.addScriptTag({content:read(f)});await page.addScriptTag({content:escapeSource+'\n'+selected(before?old:read('plateau-organisations-quetes.js'))});await page.evaluate(()=>i18next.changeLanguage('fr'));}
async function open(page,c){return page.evaluate(c=>{state.orga=c.orga;state.char=c.char;document.getElementById('postes-modal-title').textContent='Avant';document.getElementById('postes-body').textContent='Avant';document.getElementById('modal-postes').classList.remove('open');ouvrirOptionsOrga(c.orga?.id||'absente');return visible();},c);}
const seen=new Set();
async function translated(page,lang){await page.evaluate(l=>i18next.changeLanguage(l),lang);for(const node of await page.locator('#modal-postes [data-i18n]').all()){const key=await node.getAttribute('data-i18n');seen.add(key);assert.equal(await node.textContent(),await page.evaluate(k=>i18next.t(k),key));assert.equal(await node.getAttribute('dir'),lang==='ar'?'rtl':null);}const ph=page.locator('#orga-devise-input');if(await ph.count()){seen.add('organizationSettings.mottoPlaceholder');assert.equal(await ph.getAttribute('placeholder'),await page.evaluate(()=>i18next.t('organizationSettings.mottoPlaceholder')));}assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);assert.equal(await page.locator('.modal-box').evaluate(e=>e.scrollWidth>e.clientWidth),false);}
const upload={name:'sigle.png',mimeType:'image/png',buffer:Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/l9sAAAAASUVORK5CYII=','base64')};
test('paramètres : français/droits identiques, neuf langues, 320/390/1280, saisies et fichier conservés sans sauvegarde ni requête',async()=>{const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});let switches=0;try{for(const width of [320,390,1280]){const p=await browser.newPage({viewport:{width,height:900}}),before=await browser.newPage({viewport:{width,height:900}}),errors=[],requests=[];p.on('pageerror',e=>errors.push(String(e)));p.on('request',r=>requests.push(r.url()));await setup(p);await setup(before,true);
for(const c of cases){for(const page of [p,before])await page.evaluate(()=>i18next.changeLanguage('fr'));assert.deepEqual(await open(p,c),await open(before,c),c.id+' : français entier et contrôles identiques');const snapshot=await p.evaluate(()=>snapshot()),fields=await p.locator('#postes-body input').count(),toggle=await p.locator('[onclick^="toggleVisibiliteOrga"]').count();assert.equal(toggle,c.orga?.type==='criminelle'&&c.char?.name==='Alice'?1:0);for(const lang of langs){await translated(p,lang);assert.equal(await p.evaluate(()=>snapshot()),snapshot);assert.equal(await p.locator('#postes-body input').count(),fields);assert.equal(await p.locator('[onclick^="toggleVisibiliteOrga"]').count(),toggle);switches++;}}
// Saisie URL, nom et devise : valeurs, curseur, focus et prévisualisation restent identiques.
for(const page of [p,before]){await open(page,cases[0]);await page.locator('#orga-rename-input').fill(`Nouveau O'Brien <原> اسم`);await page.locator('#orga-devise-input').fill('Sauvegarder & devise libre — 原 اسم');await page.locator('#orga-avatar-input').fill('https://exemple.test/nouveau.webp');await page.locator('#orga-devise-input').focus();await page.evaluate(()=>{document.getElementById('orga-devise-input').setSelectionRange(3,11);window.keptInput=document.getElementById('orga-devise-input');});}assert.deepEqual(await p.evaluate(()=>form()),await before.evaluate(()=>form()));const typed=await p.evaluate(()=>snapshot());for(const lang of langs){await translated(p,lang);assert.equal(await p.evaluate(()=>snapshot()),typed);assert.deepEqual(await p.evaluate(()=>({same:keptInput===document.getElementById('orga-devise-input'),focus:document.activeElement.id,start:keptInput.selectionStart,end:keptInput.selectionEnd})),{same:true,focus:'orga-devise-input',start:3,end:11});switches++;}
// Fichier réel via l'input : le span du libellé ne détruit jamais le contrôle.
for(const page of [p,before]){await page.locator('input[type=file]').setInputFiles(upload);await page.evaluate(()=>{window.keptFile=_orgaAvatarFileTemp;window.keptFileInput=document.querySelector('input[type=file]');});}assert.deepEqual(await p.evaluate(()=>form()),await before.evaluate(()=>form()));const file=await p.evaluate(()=>snapshot());for(const lang of langs){await translated(p,lang);assert.equal(await p.evaluate(()=>snapshot()),file);assert.deepEqual(await p.evaluate(()=>({file:keptFile===_orgaAvatarFileTemp,input:keptFileInput===document.querySelector('input[type=file]'),name:keptFileInput.files[0].name})),{file:true,input:true,name:'sigle.png'});switches++;}for(const page of [p,before]){await page.locator('[onclick^="sauvegarderOptionsOrga"]').click();await page.locator('[onclick^="sauvegarderOptionsOrga"]').focus();await page.keyboard.press('Enter');await open(page,cases.find(c=>c.id==='criminelle'));await page.locator('[onclick^="toggleVisibiliteOrga"]').click();await page.locator('[onclick^="dissoudreOrga"]').click();}assert.deepEqual(await p.evaluate(()=>calls),await before.evaluate(()=>calls));assert.equal((await p.evaluate(()=>calls)).length,4);
for(let i=0;i<3;i++){await open(p,cases[0]);await p.locator('.modal-close').click();const s=await p.evaluate(()=>snapshot());await p.evaluate(()=>i18next.changeLanguage('ar'));assert.equal(await p.locator('#modal-postes').evaluate(e=>e.classList.contains('open')),false);assert.equal(await p.evaluate(()=>snapshot()),s);}
await p.evaluate(()=>{document.getElementById('postes-modal-title').textContent='Fenêtre voisine';document.getElementById('postes-body').textContent='Autre corps';});await p.evaluate(()=>i18next.changeLanguage('de'));assert.equal(await p.locator('#postes-modal-title').textContent(),'Fenêtre voisine');await p.evaluate(()=>{delete i18next.getResourceBundle('de','translation').organizationSettings;});await open(p,cases[0]);assert.equal(await p.locator('[onclick^="sauvegarderOptionsOrga"]').textContent(),'Sauvegarder');await p.evaluate(()=>{window.RPI18nPlateau=undefined;});const fallback=await open(p,cases[0]);assert.equal(fallback.title,'Parametres — Groupe 原 اسم');assert.ok(fallback.body.includes('AVATAR DE L\'ORGANISATION'));assert.deepEqual(errors,[]);assert.ok(requests.every(url=>url.startsWith('blob:')),requests.join('\n'));await p.close();await before.close();}assert.equal(switches,432);assert.equal(seen.size,15);console.log('14 états + saisie URL et fichier, 432 bascules ; quinze clés exercées.');}finally{await browser.close();}});
